package com.commutemate.ride;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="locations") public class Location { @Id @GeneratedValue private UUID id; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(nullable=false) private String name; @Column(nullable=false) private double latitude; @Column(nullable=false) private double longitude; @Column(nullable=false) private String timezone; @Column(nullable=false) private boolean active=true; protected Location(){} public Location(UUID tenantId,String name,double latitude,double longitude,String timezone){this.tenantId=tenantId;this.name=name;this.latitude=latitude;this.longitude=longitude;this.timezone=timezone;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getName(){return name;} public double getLatitude(){return latitude;} public double getLongitude(){return longitude;} public String getTimezone(){return timezone;} public boolean isActive(){return active;} }
